<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import type {VerifiedPlatformContext} from '@/entities/workspace/model/proof'
import {eventBus} from '@/shared/events/bus'
import {useLiveQuery} from '@/shared/lib/use-live-query'
import DataTable from '@/shared/ui/data-table/DataTable.vue'
import StatusBadge from '@/shared/ui/StatusBadge.vue'
import RelativeTime from '@/shared/ui/RelativeTime.vue'
import {Dialog,DialogContent,DialogHeader,DialogTitle,DialogDescription} from '@/shared/ui/dialog'
interface Agent {id:string;project_uuid:string;parent_agent_id:string|null;name:string;enabled:boolean;created_at:string}
const props=defineProps<{context:VerifiedPlatformContext;projectId:string|null}>()
const rows=ref<Agent[]>([]),selected=ref<Agent|null>(null),loading=ref(false),error=ref('')
let generation=0,controller=new AbortController()
const project=computed(()=>props.context.projects.find(p=>p.id===props.projectId))
function valid(row:Agent){return row&&typeof row.id==='string'&&row.project_uuid===props.projectId&&typeof row.name==='string'&&typeof row.enabled==='boolean'}
async function load(){if(!props.projectId)return;const run=generation;loading.value=true;error.value='';try{const all:Agent[]=[];let cursor:string|undefined;do{const page=await eventBus.request<{items:Agent[];has_more:boolean;next_cursor:string|null}>('agents.list',{project_uuid:props.projectId,...(cursor?{cursor}:{}),limit:100},controller.signal);if(run!==generation)return;if(!Array.isArray(page.items)||!page.items.every(valid))throw Error('Invalid agent directory');all.push(...page.items);if(!page.has_more)break;if(!page.next_cursor||page.next_cursor===cursor)throw Error('Invalid directory cursor');cursor=page.next_cursor}while(cursor);rows.value=all;if(selected.value&&!all.some(a=>a.id===selected.value!.id))selected.value=null}catch{if(run===generation)error.value='Не удалось получить агентов выбранного проекта.'}finally{if(run===generation)loading.value=false}}
async function open(row:Agent){const run=generation;try{const result=await eventBus.request<{item:Agent}>('agents.get',{project_uuid:props.projectId,id:row.id},controller.signal);if(run===generation&&valid(result.item))selected.value=result.item}catch{if(run===generation)error.value='Не удалось получить выбранного агента.'}}
const columns=[{key:'name',title:'Агент',dataIndex:'name'},{key:'parent',title:'Родительский агент',dataIndex:'parent_agent_id'},{key:'state',title:'Состояние',dataIndex:'enabled'},{key:'created',title:'Создан',dataIndex:'created_at'}]
watch(()=>[props.projectId,props.context.user.id],()=>{generation++;controller.abort();controller=new AbortController();rows.value=[];selected.value=null;error.value=''},{immediate:true})
useLiveQuery(load,{enabled:()=>!!props.projectId,topics:['management.events'],accept:e=>e.type.startsWith('agent.')})
onBeforeUnmount(()=>{generation++;controller.abort()})
</script>
<template><section class="space-y-4"><div><h2 class="text-lg font-semibold">Агенты</h2><p class="text-sm text-muted-foreground">{{project?.name||'Выберите проект в шапке'}} · зарегистрированные идентичности агентов, отдельно от сеансов выполнения.</p></div><p v-if="error" role="alert" class="text-sm text-destructive">{{error}}</p><DataTable v-if="projectId" :rows="rows" :columns="columns" label="Агенты проекта" :loading="loading" selectable @select="open"><template #cell="{row,column}"><span v-if="column.key==='name'" :title="row.id">{{row.name}}</span><span v-else-if="column.key==='parent'" :title="row.parent_agent_id||''">{{row.parent_agent_id?(rows.find(a=>a.id===row.parent_agent_id)?.name||'Агент недоступен'):'—'}}</span><StatusBadge v-else-if="column.key==='state'" :label="row.enabled?'Активен':'Отключён'" :tone="row.enabled?'success':'neutral'"/><RelativeTime v-else :value="row.created_at"/></template></DataTable><p v-if="projectId&&!loading&&!error&&!rows.length" class="text-sm text-muted-foreground">В этом проекте агенты ещё не зарегистрированы.</p><Dialog :open="!!selected" @update:open="v=>{if(!v)selected=null}"><DialogContent><DialogHeader><DialogTitle>{{selected?.name}}</DialogTitle><DialogDescription>Зарегистрированный агент выбранного проекта</DialogDescription></DialogHeader><dl v-if="selected" class="space-y-3 text-sm"><div><dt class="text-muted-foreground">Идентификатор</dt><dd class="break-all font-mono">{{selected.id}}</dd></div><div><dt class="text-muted-foreground">Состояние</dt><dd>{{selected.enabled?'Активен':'Отключён'}}</dd></div><div><dt class="text-muted-foreground">Родитель</dt><dd class="break-all">{{selected.parent_agent_id?rows.find(a=>a.id===selected?.parent_agent_id)?.name||selected.parent_agent_id:'Нет'}}</dd></div><div><dt class="text-muted-foreground">Создан</dt><dd><RelativeTime :value="selected.created_at"/></dd></div></dl></DialogContent></Dialog></section></template>
